using Meziantou.Framework.Imaging.TestHarness.Adapters;
using Meziantou.Framework.Imaging.TestHarness.Fixtures;
using Meziantou.Framework.Imaging.TestHarness.Golden;
using Meziantou.Framework.Imaging.TestHarness.Jpeg2000;
using Meziantou.Framework.Imaging.TestHarness.Pixels;

namespace Meziantou.Framework.Imaging.Tests.Conformance;

/// <summary>
/// JPEG 2000 decoding against the corpus generated by <c>tools/Meziantou.Framework.Imaging.CorpusGenerator/Jp2Corpus.cs</c>.
/// The eager, sequential and identify suites already compare every fixture under its policy; these tests check that the
/// fixtures cover the decoder features, that the reversible path is exact, and pin each policy of a decoded reference to
/// the measurement: the tolerance must be exactly the one the generator derives from the measured maximum and mean errors
/// of the library against the reference (<c>LibraryJp2Measurements</c>: max(1, measured max), measured mean + 0.01 rounded
/// up to 0.01, never above what the cross-check with an independent decoder justifies), so a numerical change of the
/// decoder is noticed and reviewed.
/// </summary>
public sealed class Jpeg2000DecoderConformanceTests
{
    private static IEnumerable<GoldenFixture> Valid => GoldenCorpus.Default.GetIds(format: "jp2", kind: FixtureKinds.Valid).Select(id => GoldenCorpus.Default.Get(id));

    public static TheoryData<string> LossyFixtures => [.. Valid.Where(fixture => !fixture.Policy.IsExact).Select(fixture => fixture.Id)];

    public static TheoryData<string> ExactFixtures => [.. Valid.Where(fixture => fixture.Policy.IsExact).Select(fixture => fixture.Id)];

    public static TheoryData<string> FixturesWithBoxesAfterTheCodestream => [.. Valid.Where(FixtureTraits.HasBoxesAfterTheCodestream).Select(fixture => fixture.Id)];

    public static TheoryData<string> Fixtures => [.. Valid.Select(fixture => fixture.Id)];

    [Fact]
    public void FixturesCoverTheDecoderFeatures()
    {
        var fixtures = Valid.ToList();
        var features = fixtures.SelectMany(fixture => fixture.Entry.Features ?? []).ToHashSet(StringComparer.Ordinal);
        foreach (var feature in new[]
        {
            "jp2.file=codestream", "jp2.file=jp2", "jp2.brand=jp2", "jp2.brand=jph",
            "jp2.components=1", "jp2.components=2", "jp2.components=3", "jp2.components=4", "jp2.bits=2", "jp2.bits=4", "jp2.bits=8", "jp2.bits=12", "jp2.bits=16",
            "jp2.transform=5-3", "jp2.transform=9-7", "jp2.componentTransform", "jp2.quantization=none", "jp2.quantization=expounded",
            "jp2.levels=0", "jp2.levels=1", "jp2.levels=2", "jp2.levels=6",
            "jp2.progression=lrcp", "jp2.progression=rlcp", "jp2.progression=rpcl", "jp2.progression=pcrl", "jp2.progression=cprl", "jp2.poc",
            "jp2.layers", "jp2.precincts", "jp2.tiles", "jp2.tileParts", "jp2.offsets", "jp2.subsampling",
            "jp2.sop", "jp2.eph", "jp2.plt", "jp2.tlm", "jp2.ppm", "jp2.ppt", "jp2.coc", "jp2.qcc", "jp2.tileCodingStyle", "jp2.roi",
            "jp2.style=bypass", "jp2.style=reset", "jp2.style=termall", "jp2.style=causal", "jp2.style=pterm", "jp2.style=segsym",
            "jp2.ht", "jp2.ht.sigProp", "jp2.ht.magRef", "jp2.ht.placeholders",
            "jp2.color=enumerated", "jp2.color=icc", "jp2.colorSpace=srgb", "jp2.colorSpace=gray", "jp2.colorSpace=sycc", "jp2.palette", "jp2.opacity",
            "jp2.box=cdef", "jp2.box=cmap", "jp2.box=pclr", "jp2.box=res", "jp2.box=resc", "jp2.box=uuid", "jp2.boxesAfterCodestream", "jp2.metadataAfterCodestream",
        })
        {
            Assert.Contains(feature, features);
        }

        // Every pixel format the decoder returns, and decoded references with and without alpha
        foreach (var pixelFormat in new[] { "Gray8", "Gray16", "Rgb24", "Rgba32", "Rgba64" })
        {
            Assert.Contains(fixtures, fixture => fixture.Expected.PixelFormat == pixelFormat);
        }

        foreach (var colorModel in new[] { "Grayscale", "GrayscaleAlpha", "Rgb", "Rgba", "Indexed", "YCbCr" })
        {
            Assert.Contains(fixtures, fixture => fixture.Expected.ColorModel == colorModel);
        }

        Assert.Contains(fixtures, fixture => !fixture.Policy.IsExact && fixture.Expected.PixelFormat == "Rgba32");
        Assert.Contains(fixtures, fixture => !fixture.Policy.IsExact && fixture.Expected.PixelFormat == "Gray8");
        Assert.Contains(fixtures, fixture => !fixture.Policy.IsExact && fixture.Expected.PixelFormat == "Rgb48");
        Assert.Contains(fixtures, fixture => !fixture.Policy.IsExact && fixture.Entry.HasFeature("jp2.ht"));
        Assert.Contains(fixtures, fixture => fixture.Expected.Resolution is not null);
        Assert.Contains(fixtures, fixture => fixture.Expected.Orientation != 1);
    }

    [Theory]
    [MemberData(nameof(Fixtures))]
    public void TheFeaturesAreThoseOfTheIndependentReader(string id)
    {
        // The generator derives the feature tags from the structure the independent reader reads: the size, the depth
        // and the kind of file the library reports are those of the same structure
        var fixture = GoldenCorpus.Default.Get(id);
        var data = fixture.ReadInput();
        var file = ReferenceJpeg2000.Parse(data);
        var info = Image.Identify(data);
        Assert.Equal((file.Width, file.Height), (info.Width, info.Height));
        Assert.Equal(file.IsFile, fixture.Entry.HasFeature("jp2.file=jp2"));
        Assert.Equal(file.PaletteEntryCount > 0 ? file.PaletteDepths[0] : file.Components[0].Precision, info.BitsPerComponent);
        Assert.True(file.HasEndOfCodestream);
        Assert.Equal(file.TileCount > 1, fixture.Entry.HasFeature("jp2.tiles"));
    }

    [Theory]
    [MemberData(nameof(ExactFixtures))]
    public void ExactFixturesDecodeToTheReferenceSamples(string id)
    {
        var fixture = GoldenCorpus.Default.Get(id);
        using var image = Image.Load(fixture.ReadInput());
        var snapshot = ImageSnapshots.Capture(image);
        Assert.Equal(fixture.Expected.FrameCount, snapshot.Frames.Count);
        for (var i = 0; i < snapshot.Frames.Count; i++)
        {
            var actual = snapshot.Frames[i].Pixels;
            var expected = fixture.GetFrame(i, actual.Layout);
            Assert.True(expected.Span.SequenceEqual(actual.Span), $"{id} frame {i} differs from the reference (the colors of fully transparent pixels included).");
        }
    }

    [Theory]
    [MemberData(nameof(LossyFixtures))]
    public void ToleranceIsTheMeasuredDisagreementWithTheReference(string id)
    {
        var fixture = GoldenCorpus.Default.Get(id);
        using var image = Image.Load(fixture.ReadInput());
        var snapshot = ImageSnapshots.Capture(image);
        Assert.Equal(fixture.Expected.FrameCount, snapshot.Frames.Count);
        var max = 0;
        var sum = 0.0;
        var location = "(none)";
        for (var i = 0; i < snapshot.Frames.Count; i++)
        {
            var actual = snapshot.Frames[i].Pixels;
            var (frameMax, frameMean, frameLocation) = Measure(fixture.GetFrame(i, actual.Layout), actual);
            sum += frameMean;
            if (frameMax > max)
            {
                max = frameMax;
                location = string.Create(CultureInfo.InvariantCulture, $"frame {i} {frameLocation}");
            }
        }

        // Errors on the 8-bit scale: a unit of a 16-bit sample is 1/257
        var scale = snapshot.Frames[0].Pixels.Layout.ScaleFrom8Bit;
        var mean = Math.Round(sum / snapshot.Frames.Count / scale, 4, MidpointRounding.AwayFromZero);
        var units = (max + scale - 1) / scale;
        var measurement = string.Create(CultureInfo.InvariantCulture, $"[\"{id}\"] = ({units}, {mean:0.0###}), // max {max} at {location}");
        TestContext.Current.TestOutputHelper?.WriteLine(measurement);

        var policy = fixture.Policy;
        var checks = fixture.Entry.Reference?.CrossChecks?.Where(check => check.ExcludedFromTolerance != true && check.MaxAbsoluteError is not null).ToList() ?? [];
        Assert.NotEmpty(checks);
        var (justifiedMax, justifiedMean) = ComparisonPolicy.GetMaximumJustifiedTolerance(checks.Max(check => check.MaxAbsoluteError!.Value), checks.Max(check => check.MeanAbsoluteError!.Value));
        var expectedMax = Math.Min(justifiedMax, Math.Max(1, units));
        var expectedMean = Math.Min(justifiedMean, Math.Ceiling(Math.Round((mean + 0.01) * 100, 6, MidpointRounding.AwayFromZero)) / 100);
        Assert.True(policy.MaxAbsoluteError == expectedMax && Math.Abs(policy.MaxMeanAbsoluteError - expectedMean) < 1e-9,
            string.Create(CultureInfo.InvariantCulture, $"The policy of '{id}' (max {policy.MaxAbsoluteError}, mean {policy.MaxMeanAbsoluteError}) is not the one derived from the measured disagreement (max {expectedMax}, mean {expectedMean}). Update LibraryJp2Measurements in tools/Meziantou.Framework.Imaging.CorpusGenerator/Jp2Corpus.cs and regenerate: {measurement}"));
    }

    [Theory]
    [MemberData(nameof(FixturesWithBoxesAfterTheCodestream))]
    public void AFileCutAfterItsCodestreamIsCompleteAndEveryOtherPrefixIsTruncated(string id)
    {
        // The boxes that follow the codestream are not needed to decode the image: the file that ends before any of them is
        // a complete file. Every other proper prefix is a truncated file, a box that is cut included
        var fixture = GoldenCorpus.Default.Get(id);
        var data = fixture.ReadInput();
        var file = ReferenceJpeg2000.Parse(data);
        Assert.True(file.IsFile);
        var boundaries = new HashSet<int>();
        var position = 0;
        var seenCodestream = false;
        while (position < data.Length)
        {
            var size = checked((int)System.Buffers.Binary.BinaryPrimitives.ReadUInt32BigEndian(data.AsSpan(position)));
            var type = System.Text.Encoding.Latin1.GetString(data, position + 4, 4);
            position += size;
            seenCodestream |= type == "jp2c";
            if (seenCodestream && position < data.Length)
            {
                boundaries.Add(position);
            }
        }

        Assert.NotEmpty(boundaries);
        var expected = GetPixels(data);
        for (var length = 0; length < data.Length; length++)
        {
            var prefix = data.AsSpan(0, length).ToArray();
            if (boundaries.Contains(length))
            {
                Assert.True(expected.AsSpan().SequenceEqual(GetPixels(prefix)), $"{id} cut at {length} bytes decodes to other pixels.");
                continue;
            }

            var exception = Catch(() => Image.Load(prefix).Dispose());
            Assert.True(exception is InvalidImageContentException or UnknownImageFormatException, $"{id} cut at {length} bytes: {exception?.GetType().Name ?? "no exception"}.");
            exception = Catch(() => Image.Identify(prefix, new ImageIdentifyOptions { Mode = ImageIdentifyMode.FullScan }));
            Assert.True(exception is InvalidImageContentException or UnknownImageFormatException, $"{id} cut at {length} bytes, full scan: {exception?.GetType().Name ?? "no exception"}.");
        }
    }

    private static Rgba64[] GetPixels(byte[] data)
    {
        using var image = Image.Load<Rgba64>(data);
        var pixels = new Rgba64[image.Width * image.Height];
        image.Frames[0].CopyPixelDataTo(pixels);
        return pixels;
    }

    private static ImageException? Catch(Action action)
    {
        try
        {
            action();
            return null;
        }
        catch (ImageException exception)
        {
            return exception;
        }
    }

    private static (int Max, double Mean, string Location) Measure(RawPixelBuffer expected, RawPixelBuffer actual)
    {
        Assert.Equal(expected.Layout, actual.Layout);
        Assert.Equal((expected.Width, expected.Height), (actual.Width, actual.Height));
        var channels = expected.Layout.ChannelCount;
        var max = 0;
        var sum = 0L;
        var count = 0;
        var location = "(none)";
        for (var y = 0; y < expected.Height; y++)
        {
            for (var x = 0; x < expected.Width; x++)
            {
                for (var c = 0; c < channels; c++)
                {
                    var difference = Math.Abs(expected.GetSample(x, y, c) - actual.GetSample(x, y, c));
                    if (c == 3)
                    {
                        Assert.Equal(0, difference); // alpha is stored without loss
                        continue;
                    }

                    sum += difference;
                    count++;
                    if (difference > max)
                    {
                        max = difference;
                        location = string.Create(CultureInfo.InvariantCulture, $"({x}, {y}) channel {c}");
                    }
                }
            }
        }

        return (max, (double)sum / count, location);
    }
}
